-- Targeted Listening 05: install the ten recordings the owner listened to and approved (2026-10-20 07:14 Asia/Bishkek,
-- IELTS Approval Queue decision message). A practice and a fresh check for each of distractor resistance, paraphrase
-- recognition, sequencing, speaker attitude and speaker purpose. Named-student pilot (Gulzada) with requires_review:
-- Jess confirms content before allocation; no release row is created. Audio is in the private ielts-targeted-listening
-- bucket, uploaded by exact SHA-256 and verified by download. An originality review is recorded per task: the automated
-- comparison found no shared text, questions, recording or script, and the owner listened to each exact recording.

insert into private.ielts_learning_tasks(code,title,purpose,audio_path,audio_sha256,taxonomy_version_id,pilot_student,version,skill,instructions,success_description,questions,content,requires_review,review_record,content_sha256) values('bh-ielts-targeted-listening-l5-v1','Rent a garden plot: Greenway Allotments','guided_practice','targeted-listening-05/a45632cd2e752097f850cb53febe2c207a7324e97438c38aa910ecf17feaf96a/BH-TL05-L5_v1.mp3','a45632cd2e752097f850cb53febe2c207a7324e97438c38aa910ecf17feaf96a','d4ad52b6-fd0f-4068-9982-28b89ff389c5','b30e9c28-96f1-4d34-83e9-9b28b4926f42','0.1.0','listening','You will hear a telephone conversation between a woman and an officer at a community garden. Answer questions 1 to 6. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. You may pause or replay for practice.','Each answer is mentioned after a wrong option. Wait for the speaker to correct, update or reject the first detail before you write.','[{"id": "q1", "prompt": "Yearly cost of a small plot: £", "accepted_answers": ["35", "thirty-five", "thirty five"], "taxonomy_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2", "supporting_node_id": "d5b1fddb-ba6f-4be1-8513-bb26d822357a"}, {"id": "q2", "prompt": "Plot location: next to the", "accepted_answers": ["greenhouse", "the greenhouse"], "taxonomy_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2", "supporting_node_id": "d0aa0bad-ecfa-4598-8f2f-07e93d3fa59b"}, {"id": "q3", "prompt": "Start date", "accepted_answers": ["15 March", "15th March", "March 15", "March 15th", "fifteenth March"], "taxonomy_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2", "supporting_node_id": "0dbe1c8f-403a-493f-afd3-c219310fb18a"}, {"id": "q4", "prompt": "Must bring a", "accepted_answers": ["padlock"], "taxonomy_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2", "supporting_node_id": "d0aa0bad-ecfa-4598-8f2f-07e93d3fa59b"}, {"id": "q5", "prompt": "Adviser''s surname", "accepted_answers": ["Price"], "taxonomy_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2", "supporting_node_id": "d0aa0bad-ecfa-4598-8f2f-07e93d3fa59b"}, {"id": "q6", "prompt": "Payment method", "accepted_answers": ["bank transfer", "transfer"], "taxonomy_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2", "supporting_node_id": "d0aa0bad-ecfa-4598-8f2f-07e93d3fa59b"}]'::jsonb,'{"scope": "Original IELTS-style targeted Listening practice; not an official IELTS recording or a band assessment.", "focus": "Distractor resistance", "teacher_notes": "Transcript:\nOfficer: Good afternoon, Greenway Allotments. How can I help?\nCaller: Hi. I''d like to rent a garden plot. A friend told me the small plots are thirty pounds a year.\nOfficer: They were, but the price went up in January. A small plot is now thirty-five pounds a year.\nCaller: That''s fine. Could I have one near the car park? I''ll be carrying tools.\nOfficer: The car park plots have all gone, I''m afraid. The nearest free ones are beside the greenhouse. It''s only a short walk.\nCaller: Next to the greenhouse, then. When could I start?\nOfficer: New tenants usually begin on the first of March, but the paths are being repaired this year, so you''ll start on the fifteenth of March.\nCaller: OK. Do I need my own spade and fork?\nOfficer: No, we lend those free of charge. What you do need is a padlock for the tool box on your plot.\nCaller: A padlock. Right. Is there anyone I can ask for advice? I''ve never grown vegetables.\nOfficer: Our manager, Mr Hughes, used to help beginners, but he''s retired now. Ask Joanna Price. She''s our volunteer adviser. That''s P, R, I, C, E.\nCaller: Joanna Price. And how should I pay?\nOfficer: We don''t take cash any more, and the card machine is broken, so please pay by bank transfer.\nCaller: Bank transfer. Thanks very much.\n\nKey and teaching notes:\nq1: 35 / thirty-five / thirty five. Thirty pounds was the old price; it is now thirty-five. Primary: Distractor resistance; supporting: Numerical information.\nq2: greenhouse / the greenhouse. The car park plots have gone; the free plots are beside the greenhouse. Primary: Distractor resistance; supporting: Explicit detail.\nq3: 15 March / 15th March / March 15 / March 15th / fifteenth March. The usual date is 1 March; this year it is the fifteenth. Primary: Distractor resistance; supporting: Dates and times.\nq4: padlock. A spade and fork are lent free; the caller needs a padlock. Primary: Distractor resistance; supporting: Explicit detail.\nq5: Price. Mr Hughes has retired; the adviser is Joanna Price. Primary: Distractor resistance; supporting: Explicit detail.\nq6: bank transfer / transfer. Cash is no longer taken and the card machine is broken. Primary: Distractor resistance; supporting: Explicit detail."}'::jsonb,true,'{"audio_approval": {"reviewer": "Sobbi (Brains Heist owner)", "date": "2026-10-20", "source_statement": "Listened and approved (IELTS Approval Queue decision message, 2026-10-20 07:14 Asia/Bishkek)", "scope": "Approval of this exact recording. Installed for the named-student pilot; teacher content confirmation remains required for assignment. No calibration or wider-release approval inferred.", "files": [{"file": "BH-TL05-L5_v1.mp3", "sha256": "a45632cd2e752097f850cb53febe2c207a7324e97438c38aa910ecf17feaf96a"}]}, "draft_reference": "docs/ielts/practice/TARGETED_LISTENING_05.json", "script_sha256": "236c7608b5b8d305166172195285f7fe463a5f959df7e04927e5b060368f7ebd", "voices": {"OFFICER": "James", "CALLER": "Paula"}, "provider": "Runway (ElevenLabs eleven_v4 dialogue; eleven_multilingual_v2 narrator)", "copyright_intro": "This recording is copyright Brains Heist LLC. All rights reserved.", "audio_file": {"file": "BH-TL05-L5_v1.mp3", "sha256": "a45632cd2e752097f850cb53febe2c207a7324e97438c38aa910ecf17feaf96a", "bytes": 3574389, "duration_seconds": 148.896, "integrated_lufs": -18.5, "true_peak_dbfs": -1.5, "decoded_clipped_samples": 0, "detected_pauses_seconds": [30.149, 15.097], "human_review": "Owner listened and approved, 2026-10-20; exact-file audio scope."}, "installation_verified": "2026-10-20", "teacher_content_review": "Required before assignment; no teacher confirmation recorded by installation."}'::jsonb,'ec4c5c4a7defa4d5453fb7e0c01563725c76b53f4890a154905ee2c665de3163') on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,title,purpose,audio_path,audio_sha256,taxonomy_version_id,pilot_student,version,skill,instructions,success_description,questions,content,requires_review,review_record,content_sha256) values('bh-ielts-targeted-listening-l6-v1','Join a running club: Northgate Runners','independent_check','targeted-listening-05/7e494ee370337c64a6135a10d5c7e5e0b4af2d8144e5d25e4391f16f89448d63/BH-TL05-L6_v1.mp3','7e494ee370337c64a6135a10d5c7e5e0b4af2d8144e5d25e4391f16f89448d63','d4ad52b6-fd0f-4068-9982-28b89ff389c5','b30e9c28-96f1-4d34-83e9-9b28b4926f42','0.1.0','listening','You will hear a telephone conversation between a woman and a coach at a running club. Answer questions 1 to 6. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. This is a fresh check: listen once, without pausing, and answer on your own.','Each answer is mentioned after a wrong option. Write the final, confirmed detail.','[{"id": "q1", "prompt": "Beginners'' day", "accepted_answers": ["Wednesday", "Wednesdays"], "taxonomy_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2", "supporting_node_id": "0dbe1c8f-403a-493f-afd3-c219310fb18a"}, {"id": "q2", "prompt": "Start time", "accepted_answers": ["6:30", "6.30", "18:30", "six thirty", "6:30pm", "6.30pm", "6:30 pm", "6.30 pm"], "taxonomy_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2", "supporting_node_id": "0dbe1c8f-403a-493f-afd3-c219310fb18a"}, {"id": "q3", "prompt": "Meet outside the", "accepted_answers": ["library", "the library"], "taxonomy_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2", "supporting_node_id": "d0aa0bad-ecfa-4598-8f2f-07e93d3fa59b"}, {"id": "q4", "prompt": "Cost of the trial month: £", "accepted_answers": ["12", "twelve"], "taxonomy_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2", "supporting_node_id": "d5b1fddb-ba6f-4be1-8513-bb26d822357a"}, {"id": "q5", "prompt": "Must wear a", "accepted_answers": ["reflective vest"], "taxonomy_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2", "supporting_node_id": "d0aa0bad-ecfa-4598-8f2f-07e93d3fa59b"}, {"id": "q6", "prompt": "On arrival, ask for", "accepted_answers": ["Helen"], "taxonomy_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2", "supporting_node_id": "d0aa0bad-ecfa-4598-8f2f-07e93d3fa59b"}]'::jsonb,'{"scope": "Original IELTS-style targeted Listening fresh check; not an official IELTS recording or a band assessment.", "focus": "Distractor resistance", "teacher_notes": "Transcript:\nCaller: Hello, is that Northgate Running Club? I saw a poster about joining.\nCoach: Yes, it is. I''m Sam, one of the coaches. What would you like to know?\nCaller: The poster says beginners meet on Tuesdays.\nCoach: We used to, but a school has booked the track on Tuesdays, so beginners meet on Wednesdays now.\nCaller: Wednesday''s fine. What time?\nCoach: Seven o''clock in summer, but it gets dark early at this time of year, so we start at six thirty.\nCaller: And where do you meet? At the sports hall?\nCoach: The sports hall is closed for painting. Meet us outside the library instead. It''s well lit, so it''s safe.\nCaller: The library. Is there a membership fee?\nCoach: Adults pay forty pounds a year, but the first month is a trial, and that costs twelve pounds.\nCaller: I''ll start with the trial, then. Do I need special running shoes?\nCoach: Ordinary trainers are fine at first. The one thing we insist on is a reflective vest, so drivers can see you.\nCaller: A reflective vest. And who should I ask for when I arrive? You?\nCoach: I''m away next week, so look for Helen. She leads the beginners'' group.\nCaller: Helen. Great, thanks.\n\nKey and teaching notes:\nq1: Wednesday / Wednesdays. Tuesday was on the poster; beginners now meet on Wednesdays. Primary: Distractor resistance; supporting: Dates and times.\nq2: 6:30 / 6.30 / 18:30 / six thirty / 6:30pm / 6.30pm / 6:30 pm / 6.30 pm. Seven o''clock is the summer time; now it is six thirty. Primary: Distractor resistance; supporting: Dates and times.\nq3: library / the library. The sports hall is closed; they meet outside the library. Primary: Distractor resistance; supporting: Explicit detail.\nq4: 12 / twelve. Forty pounds is the yearly fee; the trial month is twelve. Primary: Distractor resistance; supporting: Numerical information.\nq5: reflective vest. Special shoes are not needed; a reflective vest is required. Primary: Distractor resistance; supporting: Explicit detail.\nq6: Helen. Sam is away; Helen leads the beginners. Primary: Distractor resistance; supporting: Explicit detail."}'::jsonb,true,'{"audio_approval": {"reviewer": "Sobbi (Brains Heist owner)", "date": "2026-10-20", "source_statement": "Listened and approved (IELTS Approval Queue decision message, 2026-10-20 07:14 Asia/Bishkek)", "scope": "Approval of this exact recording. Installed for the named-student pilot; teacher content confirmation remains required for assignment. No calibration or wider-release approval inferred.", "files": [{"file": "BH-TL05-L6_v1.mp3", "sha256": "7e494ee370337c64a6135a10d5c7e5e0b4af2d8144e5d25e4391f16f89448d63"}]}, "draft_reference": "docs/ielts/practice/TARGETED_LISTENING_05.json", "script_sha256": "216521ec224f5b5d16a87271ecbcac1c2e4d26f15eab680e8576fbe53d646048", "voices": {"COACH": "Frank", "CALLER": "Kylie"}, "provider": "Runway (ElevenLabs eleven_v4 dialogue; eleven_multilingual_v2 narrator)", "copyright_intro": "This recording is copyright Brains Heist LLC. All rights reserved.", "audio_file": {"file": "BH-TL05-L6_v1.mp3", "sha256": "7e494ee370337c64a6135a10d5c7e5e0b4af2d8144e5d25e4391f16f89448d63", "bytes": 3383735, "duration_seconds": 140.952, "integrated_lufs": -18.6, "true_peak_dbfs": -1.4, "decoded_clipped_samples": 0, "detected_pauses_seconds": [30.143, 15.097], "human_review": "Owner listened and approved, 2026-10-20; exact-file audio scope."}, "installation_verified": "2026-10-20", "teacher_content_review": "Required before assignment; no teacher confirmation recorded by installation."}'::jsonb,'1e11e857cc02cc2b38b80817fa98424d0a4b8d15566f15882a3b3059d5b55e22') on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,title,purpose,audio_path,audio_sha256,taxonomy_version_id,pilot_student,version,skill,instructions,success_description,questions,content,requires_review,review_record,content_sha256) values('bh-ielts-targeted-listening-l7-v1','Report on a field trip: the wetland centre','guided_practice','targeted-listening-05/9d054b008c567a96137785041d2c42b19a0ffb8570681b3ec24eda443880e2d9/BH-TL05-L7_v1.mp3','9d054b008c567a96137785041d2c42b19a0ffb8570681b3ec24eda443880e2d9','d4ad52b6-fd0f-4068-9982-28b89ff389c5','b30e9c28-96f1-4d34-83e9-9b28b4926f42','0.1.0','listening','You will hear a conversation between a tutor and a student, Daniel, about a field trip. Answer questions 1 to 6. Choose the correct letter, A, B or C, for each question. You may pause or replay for practice.','The correct option uses different words from the speaker. Options that repeat words you hear are often wrong; match the meaning, not the words.','[{"id": "q1", "prompt": "What surprised Daniel about the trip?", "options": [{"value": "A", "label": "A  There were more birds than he expected."}, {"value": "B", "label": "B  It focused mainly on controlling water."}, {"value": "C", "label": "C  The weather was worse than forecast."}], "accepted_answers": ["B"], "taxonomy_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}, {"id": "q2", "prompt": "How did the guide teach the group?", "options": [{"value": "A", "label": "A  She gave a detailed introduction."}, {"value": "B", "label": "B  She showed them a short film."}, {"value": "C", "label": "C  She encouraged them to find answers themselves."}], "accepted_answers": ["C"], "taxonomy_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}, {"id": "q3", "prompt": "How did the centre deal with flooding?", "options": [{"value": "A", "label": "A  It built higher walls."}, {"value": "B", "label": "B  It allowed some land to become wet again."}, {"value": "C", "label": "C  It sent water to a nearby river."}], "accepted_answers": ["B"], "taxonomy_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}, {"id": "q4", "prompt": "Why have visitor numbers increased?", "options": [{"value": "A", "label": "A  Earlier visitors recommended the centre."}, {"value": "B", "label": "B  There was a new advertising campaign."}, {"value": "C", "label": "C  Family tickets became cheaper."}], "accepted_answers": ["A"], "taxonomy_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}, {"id": "q5", "prompt": "Why did Daniel change his data collection?", "options": [{"value": "A", "label": "A  His equipment broke."}, {"value": "B", "label": "B  The guide advised him to."}, {"value": "C", "label": "C  Low temperatures meant there were few insects."}], "accepted_answers": ["C"], "taxonomy_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}, {"id": "q6", "prompt": "What does Daniel plan to do next?", "options": [{"value": "A", "label": "A  Visit at a different time of year."}, {"value": "B", "label": "B  Write a report for the centre."}, {"value": "C", "label": "C  Study a different wetland."}], "accepted_answers": ["A"], "taxonomy_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}]'::jsonb,'{"scope": "Original IELTS-style targeted Listening practice; not an official IELTS recording or a band assessment.", "focus": "Paraphrase recognition", "teacher_notes": "Transcript:\nTutor: So, Daniel, you''ve just come back from the wetland centre. How was the trip?\nDaniel: Better than I expected. I''d assumed it would just be birdwatching, but most of the day was about how the water is managed.\nTutor: And the guide? Was she helpful?\nDaniel: Very. She didn''t give us a long talk at the start. Instead, she stopped every few minutes and got us to work things out for ourselves.\nTutor: Good. The centre had a problem with flooding a few years ago, didn''t it?\nDaniel: Yes. The old walls kept breaking, so instead of building stronger ones, they let part of the land turn back into marsh. Now that soaks up the extra water.\nTutor: Interesting. What about visitor numbers?\nDaniel: They''ve gone up, but not because of advertising. The guide said it''s mainly families who came once and then told their friends.\nTutor: Did you manage to collect data for your project?\nDaniel: Some. My plan was to count insects, but it was so cold there weren''t many about, so I measured the water temperature at different points instead.\nTutor: Sensible. And what will you do next?\nDaniel: I''d like to go back in spring, when it''s warmer, and repeat the measurements, so I can compare the two seasons.\n\nKey and teaching notes:\nq1: B. \"most of the day was about how the water is managed\" = controlling water. Birds are mentioned but were not the focus. Primary: Paraphrase recognition; supporting: Distractor resistance.\nq2: C. \"got us to work things out for ourselves\" = find answers themselves. She did NOT give a long talk. Primary: Paraphrase recognition; supporting: Distractor resistance.\nq3: B. \"let part of the land turn back into marsh\" = allowed land to become wet again. \"walls\" is the trap word. Primary: Paraphrase recognition; supporting: Distractor resistance.\nq4: A. \"families who came once and then told their friends\" = recommendations. Advertising is rejected. Primary: Paraphrase recognition; supporting: Distractor resistance.\nq5: C. \"so cold there weren''t many about\" = low temperatures, few insects. Primary: Paraphrase recognition; supporting: Distractor resistance.\nq6: A. \"go back in spring ... compare the two seasons\" = a different time of year. Primary: Paraphrase recognition; supporting: Distractor resistance."}'::jsonb,true,'{"audio_approval": {"reviewer": "Sobbi (Brains Heist owner)", "date": "2026-10-20", "source_statement": "Listened and approved (IELTS Approval Queue decision message, 2026-10-20 07:14 Asia/Bishkek)", "scope": "Approval of this exact recording. Installed for the named-student pilot; teacher content confirmation remains required for assignment. No calibration or wider-release approval inferred.", "files": [{"file": "BH-TL05-L7_v1.mp3", "sha256": "9d054b008c567a96137785041d2c42b19a0ffb8570681b3ec24eda443880e2d9"}]}, "draft_reference": "docs/ielts/practice/TARGETED_LISTENING_05.json", "script_sha256": "f82a9f371d16b41637def399d33b764934601dfdc43c2f160831cb6a957ac243", "voices": {"TUTOR": "Marlene", "DANIEL": "James"}, "provider": "Runway (ElevenLabs eleven_v4 dialogue; eleven_multilingual_v2 narrator)", "copyright_intro": "This recording is copyright Brains Heist LLC. All rights reserved.", "audio_file": {"file": "BH-TL05-L7_v1.mp3", "sha256": "9d054b008c567a96137785041d2c42b19a0ffb8570681b3ec24eda443880e2d9", "bytes": 3376248, "duration_seconds": 140.64, "integrated_lufs": -18.4, "true_peak_dbfs": -1.5, "decoded_clipped_samples": 0, "detected_pauses_seconds": [30.145, 15.097], "human_review": "Owner listened and approved, 2026-10-20; exact-file audio scope."}, "installation_verified": "2026-10-20", "teacher_content_review": "Required before assignment; no teacher confirmation recorded by installation."}'::jsonb,'c44d519aa0594aeda8caa9481781a29073ae9e454aa948423d153630590df9f9') on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,title,purpose,audio_path,audio_sha256,taxonomy_version_id,pilot_student,version,skill,instructions,success_description,questions,content,requires_review,review_record,content_sha256) values('bh-ielts-targeted-listening-l8-v1','Radio interview: the new Brookfield Library','independent_check','targeted-listening-05/70bbb88ce8e9b81c3dd7ecc445bb69d0fe436c33047fc8e24382a0b344a0b5c4/BH-TL05-L8_v1.mp3','70bbb88ce8e9b81c3dd7ecc445bb69d0fe436c33047fc8e24382a0b344a0b5c4','d4ad52b6-fd0f-4068-9982-28b89ff389c5','b30e9c28-96f1-4d34-83e9-9b28b4926f42','0.1.0','listening','You will hear a radio interview with Ruth Ellis, the manager of a local library. Answer questions 1 to 6. Choose the correct letter, A, B or C, for each question. This is a fresh check: listen once, without pausing, and answer on your own.','The correct option expresses the speaker''s meaning in different words.','[{"id": "q1", "prompt": "What is the main change to the ground floor?", "options": [{"value": "A", "label": "A  More shelves have been added."}, {"value": "B", "label": "B  It has become a meeting area."}, {"value": "C", "label": "C  It is now used for storage."}], "accepted_answers": ["B"], "taxonomy_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}, {"id": "q2", "prompt": "What happened to the library''s books?", "options": [{"value": "A", "label": "A  All of them were kept."}, {"value": "B", "label": "B  Old ones were sold."}, {"value": "C", "label": "C  Some were given to schools."}], "accepted_answers": ["A"], "taxonomy_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}, {"id": "q3", "prompt": "Who paid most of the cost?", "options": [{"value": "A", "label": "A  The council."}, {"value": "B", "label": "B  Library users, through higher charges."}, {"value": "C", "label": "C  Companies in the area."}], "accepted_answers": ["C"], "taxonomy_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}, {"id": "q4", "prompt": "What has changed about the opening hours?", "options": [{"value": "A", "label": "A  It is now open for part of Sunday."}, {"value": "B", "label": "B  It opens later on weekdays."}, {"value": "C", "label": "C  It closes earlier on Saturdays."}], "accepted_answers": ["A"], "taxonomy_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}, {"id": "q5", "prompt": "Why is a room reserved for teenagers?", "options": [{"value": "A", "label": "A  They wanted somewhere to meet friends."}, {"value": "B", "label": "B  They had no quiet place to study at home."}, {"value": "C", "label": "C  They asked for more computers."}], "accepted_answers": ["B"], "taxonomy_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}, {"id": "q6", "prompt": "What will the library do next?", "options": [{"value": "A", "label": "A  Make the building bigger."}, {"value": "B", "label": "B  Employ more staff."}, {"value": "C", "label": "C  Ask users for their opinions."}], "accepted_answers": ["C"], "taxonomy_node_id": "94c5d4f7-ab5b-464a-a1f8-4cac4f1d2d2d", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}]'::jsonb,'{"scope": "Original IELTS-style targeted Listening fresh check; not an official IELTS recording or a band assessment.", "focus": "Paraphrase recognition", "teacher_notes": "Transcript:\nInterviewer: Today I''m talking to Ruth Ellis, who manages Brookfield Library. Ruth, the library reopened last month. What''s the biggest change?\nRuth: The building looks much the same, but people use it differently. The old rows of shelves were moved upstairs, so the ground floor is now open space where groups can get together.\nInterviewer: Were people unhappy about losing the shelves?\nRuth: A few were at first. But not a single book was thrown away or sold. We still have the whole collection.\nInterviewer: How was the work paid for?\nRuth: The council had no money for it, and we didn''t want to put up our charges. In the end, local firms covered most of the bill.\nInterviewer: And the opening hours?\nRuth: Weekdays and Saturdays are the same. The real difference is Sunday. We used to be closed all day; now we open from one until five.\nInterviewer: What about young people?\nRuth: Teenagers told us there was nowhere peaceful at home to do their homework, so a room is reserved just for them after school.\nInterviewer: Finally, what''s next?\nRuth: We want to hear from the people who come here. A questionnaire goes out next week, and we''ll plan the next stage around what they tell us.\n\nKey and teaching notes:\nq1: B. \"open space where groups can get together\" = a meeting area. Primary: Paraphrase recognition; supporting: Distractor resistance.\nq2: A. \"not a single book was thrown away or sold\" = all kept. Primary: Paraphrase recognition; supporting: Distractor resistance.\nq3: C. \"local firms covered most of the bill\" = companies in the area. Primary: Paraphrase recognition; supporting: Distractor resistance.\nq4: A. \"now we open from one until five\" on Sunday = part of Sunday. Primary: Paraphrase recognition; supporting: Distractor resistance.\nq5: B. \"nowhere peaceful at home to do their homework\" = no quiet place to study. Primary: Paraphrase recognition; supporting: Distractor resistance.\nq6: C. \"A questionnaire goes out ... what they tell us\" = ask users for opinions. Primary: Paraphrase recognition; supporting: Distractor resistance."}'::jsonb,true,'{"audio_approval": {"reviewer": "Sobbi (Brains Heist owner)", "date": "2026-10-20", "source_statement": "Listened and approved (IELTS Approval Queue decision message, 2026-10-20 07:14 Asia/Bishkek)", "scope": "Approval of this exact recording. Installed for the named-student pilot; teacher content confirmation remains required for assignment. No calibration or wider-release approval inferred.", "files": [{"file": "BH-TL05-L8_v1.mp3", "sha256": "70bbb88ce8e9b81c3dd7ecc445bb69d0fe436c33047fc8e24382a0b344a0b5c4"}]}, "draft_reference": "docs/ielts/practice/TARGETED_LISTENING_05.json", "script_sha256": "3fdf2f90cc8f8d2784b866098d604037643759036a06e23b1c58c53f4ccb18f0", "voices": {"INTERVIEWER": "Vincent", "RUTH": "Paula"}, "provider": "Runway (ElevenLabs eleven_v4 dialogue; eleven_multilingual_v2 narrator)", "copyright_intro": "This recording is copyright Brains Heist LLC. All rights reserved.", "audio_file": {"file": "BH-TL05-L8_v1.mp3", "sha256": "70bbb88ce8e9b81c3dd7ecc445bb69d0fe436c33047fc8e24382a0b344a0b5c4", "bytes": 3442492, "duration_seconds": 143.4, "integrated_lufs": -18.7, "true_peak_dbfs": -1.6, "decoded_clipped_samples": 0, "detected_pauses_seconds": [30.147, 15.097], "human_review": "Owner listened and approved, 2026-10-20; exact-file audio scope."}, "installation_verified": "2026-10-20", "teacher_content_review": "Required before assignment; no teacher confirmation recorded by installation."}'::jsonb,'98e524765c5306d8ddcf9aa53a743a4c7806cd14f1cc7117affd807d8a1fd1bb') on conflict (code) do nothing;
insert into private.ielts_learning_tasks(code,title,purpose,audio_path,audio_sha256,taxonomy_version_id,pilot_student,version,skill,instructions,success_description,questions,content,requires_review,review_record,content_sha256) values('bh-ielts-targeted-listening-l9-v1','Follow a process: making recycled paper','guided_practice','targeted-listening-05/b84254c2ef86d13039cbacd60d93c4e6ba5255672bf632088ee139bd68b49021/BH-TL05-L9_v1.mp3','b84254c2ef86d13039cbacd60d93c4e6ba5255672bf632088ee139bd68b49021','d4ad52b6-fd0f-4068-9982-28b89ff389c5','b30e9c28-96f1-4d34-83e9-9b28b4926f42','0.1.0','listening','You will hear a conversation between an art instructor and a student about how to make recycled paper. Answer questions 1 to 6. Choose the correct letter, A, B or C, for each question. You may pause or replay for practice.','The steps are not always mentioned in the order they happen. Listen for "before", "once", "only then", "after" and "last" to rebuild the real order.','[{"id": "q1", "prompt": "What do students do immediately after tearing the paper?", "options": [{"value": "A", "label": "A  Blend it."}, {"value": "B", "label": "B  Soak it in warm water."}, {"value": "C", "label": "C  Pour it into a tray."}], "accepted_answers": ["B"], "taxonomy_node_id": "5bcb6e11-1f2d-4ce6-b1af-093acc342ff1", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}, {"id": "q2", "prompt": "When should colour be added?", "options": [{"value": "A", "label": "A  During blending."}, {"value": "B", "label": "B  Before soaking."}, {"value": "C", "label": "C  After pressing."}], "accepted_answers": ["A"], "taxonomy_node_id": "5bcb6e11-1f2d-4ce6-b1af-093acc342ff1", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}, {"id": "q3", "prompt": "What happens immediately before the frame is lowered?", "options": [{"value": "A", "label": "A  The pulp is blended."}, {"value": "B", "label": "B  The frame is turned over."}, {"value": "C", "label": "C  The pulp is poured into a tray of water."}], "accepted_answers": ["C"], "taxonomy_node_id": "5bcb6e11-1f2d-4ce6-b1af-093acc342ff1", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}, {"id": "q4", "prompt": "What do students do immediately after lifting the frame out?", "options": [{"value": "A", "label": "A  Leave it on the frame to dry."}, {"value": "B", "label": "B  Turn it over onto a cloth."}, {"value": "C", "label": "C  Hang it on a line."}], "accepted_answers": ["B"], "taxonomy_node_id": "5bcb6e11-1f2d-4ce6-b1af-093acc342ff1", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}, {"id": "q5", "prompt": "What is the last stage?", "options": [{"value": "A", "label": "A  Pressing with a sponge."}, {"value": "B", "label": "B  Lifting the frame."}, {"value": "C", "label": "C  Drying on a line overnight."}], "accepted_answers": ["C"], "taxonomy_node_id": "5bcb6e11-1f2d-4ce6-b1af-093acc342ff1", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}, {"id": "q6", "prompt": "Which stage comes between soaking and pouring into the tray?", "options": [{"value": "A", "label": "A  Blending."}, {"value": "B", "label": "B  Tearing."}, {"value": "C", "label": "C  Pressing."}], "accepted_answers": ["A"], "taxonomy_node_id": "5bcb6e11-1f2d-4ce6-b1af-093acc342ff1", "supporting_node_id": "f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}]'::jsonb,'{"scope": "Original IELTS-style targeted Listening practice; not an official IELTS recording or a band assessment.", "focus": "Sequencing", "teacher_notes": "Transcript:\nInstructor: Today we''re making recycled paper. Let me go through the process before you start. The very first thing is to tear your old paper into small pieces.\nStudent: Do we put the pieces straight into the blender?\nInstructor: Not yet. Before blending, the pieces need to soak in warm water for about an hour. That softens them. Once they''re soft, you blend them into a pulp.\nStudent: Can we add colour?\nInstructor: Yes. Add a little food colouring while you''re blending, not afterwards.\nStudent: And after blending, we pour it onto the frame?\nInstructor: Almost. First you pour the pulp into a tray of water. Only then do you lower the frame into the tray and lift it out slowly, so a thin layer sits on the screen.\nStudent: Then we leave it on the frame to dry?\nInstructor: No, that''s a common mistake. Straight after lifting it out, you turn the frame over onto a cloth and press out the extra water with a sponge.\nStudent: And that''s it?\nInstructor: One more stage, and it''s the last one. Hang the cloth on a line overnight to dry. In the morning, peel off your paper.\n\nKey and teaching notes:\nq1: B. The student suggests the blender, but \"Not yet. Before blending, the pieces need to soak\". Primary: Sequencing; supporting: Distractor resistance.\nq2: A. \"Add a little food colouring while you''re blending, not afterwards.\" Primary: Sequencing; supporting: Distractor resistance.\nq3: C. \"First you pour the pulp into a tray of water. Only then do you lower the frame\". Primary: Sequencing; supporting: Distractor resistance.\nq4: B. Leaving it on the frame is \"a common mistake\"; \"Straight after lifting it out, you turn the frame over\". Primary: Sequencing; supporting: Distractor resistance.\nq5: C. \"One more stage, and it''s the last one. Hang the cloth on a line overnight\". Primary: Sequencing; supporting: Distractor resistance.\nq6: A. Soak → blend → pour into the tray. Primary: Sequencing; supporting: Distractor resistance."}'::jsonb,true,'{"audio_approval": {"reviewer": "Sobbi (Brains Heist owner)", "date": "2026-10-20", "source_statement": "Listened and approved (IELTS Approval Queue decision message, 2026-10-20 07:14 Asia/Bishkek)", "scope": "Approval of this exact recording. Installed for the named-student pilot; teacher content confirmation remains required for assignment. No calibration or wider-release approval inferred.", "files": [{"file": "BH-TL05-L9_v1.mp3", "sha256": "b84254c2ef86d13039cbacd60d93c4e6ba5255672bf632088ee139bd68b49021"}]}, "draft_reference": "docs/ielts/practice/TARGETED_LISTENING_05.json", "script_sha256": "4e826ac1aa890a4c901932302a20f9cc53d4ab59275af656e9016dd7134a94a9", "voices": {"INSTRUCTOR": "Miriam", "STUDENT": "Noah"}, "provider": "Runway (ElevenLabs eleven_v4 dialogue; eleven_multilingual_v2 narrator)", "copyright_intro": "This recording is copyright Brains Heist LLC. All rights reserved.", "audio_file": {"file": "BH-TL05-L9_v1.mp3", "sha256": "b84254c2ef86d13039cbacd60d93c4e6ba5255672bf632088ee139bd68b49021", "bytes": 3418869, "duration_seconds": 142.416, "integrated_lufs": -18.9, "true_peak_dbfs": -1.2, "decoded_clipped_samples": 0, "detected_pauses_seconds": [30.153, 15.097], "human_review": "Owner listened and approved, 2026-10-20; exact-file audio scope."}, "installation_verified": "2026-10-20", "teacher_content_review": "Required before assignment; no teacher confirmation recorded by installation."}'::jsonb,'41d04757a0a6d7edceccce078fe314f4a22a4b77f8b2c0a2e77ad69a7a264738') on conflict (code) do nothing;
